import unittest
from catalog import Registry,AliasCollision
class Public(unittest.TestCase):
 def test_collision_is_deterministic(self):
  rows=[(2,'same','b'),(1,'same','a')]
  for ordered in (rows,list(reversed(rows))):
   with self.assertRaisesRegex(AliasCollision,'1.*2|2.*1'): Registry(ordered)
 def test_exact_lookup(self): self.assertEqual(Registry([(7,'x','p')]).by_exact_id(7)[2],'p')

