from .errors import AliasCollision
class Registry:
 def __init__(self,rows):
  self.by_id={row[0]:row for row in rows}
  by_alias={}
  for row in rows:
   alias=row[1]
   if alias in by_alias:
    other=by_alias[alias]
    raise AliasCollision(f"alias {alias!r} collides between id {other[0]} and id {row[0]}")
   by_alias[alias]=row
  self.by_alias=by_alias
 def by_exact_id(self,item_id): return self.by_id[item_id]
 def by_name(self,alias): return self.by_alias[alias]

